<?php require_once __DIR__ . '/db.php';  function h(string $value): string {     return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }  if (isset($_GET['ajax']) && $_GET['ajax'] === '1') {     header('Content-Type: application/json; charset=utf-8');     $q = trim($_GET['q'] ?? '');     $stmt = $pdo->prepare(       'SELECT course_id, course_name, description, duration        FROM courses        WHERE course_name LIKE :q OR description LIKE :q        ORDER BY course_name'     );     $stmt->execute(['q' => '%' . $q . '%']);     echo json_encode($stmt->fetchAll(), JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT);     exit; }  $q = trim($_GET['q'] ?? ''); if ($q !== '') {     $stmt = $pdo->prepare('SELECT course_id, course_name, description, duration FROM courses WHERE course_name LIKE :q OR description LIKE :q ORDER BY course_name');     $stmt->execute(['q' => '%' . $q . '%']); } else {     $stmt = $pdo->query('SELECT course_id, course_name, description, duration FROM courses ORDER BY course_name'); } $courses = $stmt->fetchAll(); ?> <!doctype html> <html lang="en"> <head>   <meta charset="utf-8">   <meta name="viewport" content="width=device-width, initial-scale=1">   <title>Courses | CollegeConnect</title>   <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">   <link rel="stylesheet" href="css/style.css"> </head> <body> <nav class="navbar navbar-dark site-nav"><div class="container">   <a class="navbar-brand" href="index.php">CollegeConnect</a>   <div><a class="nav-link d-inline text-white" href="index.php">Home</a><a class="nav-link d-inline textwhite" href="apply.php">Apply</a></div> </div></nav> <main class="container py-5">   <h1>Course catalogue</h1>   <label for="courseSearch" class="form-label">Search by course name or description</label>   <input id="courseSearch" class="form-control mb-4" type="search" placeholder="e.g. cybersecurity" value="<?= h($q) ?>">   <p id="searchStatus" role="status" class="small text-secondary"></p>   <div id="courseResults" class="row g-3">   <?php foreach ($courses as $course): ?>     <div class="col-md-6 col-lg-4">       <article class="card h-100"><div class="card-body">         <h2 class="h5"><?= h($course['course_name']) ?></h2>         <p><?= h($course['description']) ?></p>         <p class="small">Duration: <?= h($course['duration']) ?></p>         <a class="btn btn-brand" href="apply.php?course_id=<?= (int)$course['course_id'] ?>">Apply</a>       </div></article>     </div>   <?php endforeach; ?>   </div> </main> <script src="https://code.jquery.com/jquery-3.7.1.min.js"></script> <script src="js/script.js"></script> </body> </html> 